// AE-03 Worker B: Code Generation & Execution
// Receives: { task_description, language, context }
// Returns: CodeWorkerResult (Pydantic-compliant)

const input = $input.first().json;
const taskDesc = input.task_description || '';
const language = input.language || 'python';
const context = input.context || {};

// --- Simulated code generation ---
let generatedCode = '';
let executionOutput = null;

if (language === 'python') {
  generatedCode = `# Auto-generated for task: ${taskDesc}\n\ndef execute_task():\n    """${taskDesc}"""\n    result = {"status": "completed", "task": "${taskDesc.substring(0, 50)}"}\n    return result\n\nif __name__ == "__main__":\n    output = execute_task()\n    print(output)`;
  executionOutput = `{'status': 'completed', 'task': '${taskDesc.substring(0, 50)}'}`;
} else if (language === 'typescript') {
  generatedCode = `// Auto-generated for task: ${taskDesc}\n\nexport function executeTask(): Record<string, string> {\n  return { status: "completed", task: "${taskDesc.substring(0, 50)}" };\n}`;
  executionOutput = null;
} else {
  generatedCode = `#!/bin/bash\n# Auto-generated for task: ${taskDesc}\necho "Task completed: ${taskDesc.substring(0, 50)}"`;
  executionOutput = `Task completed: ${taskDesc.substring(0, 50)}`;
}

return [{
  json: {
    status: 'success',
    generated_code: generatedCode,
    execution_output: executionOutput,
    success: true
  }
}];
